// ============================================
// 1. GET QWEN AGENT RESPONSE
// ============================================

const raw = $json.output ?? $json.text ?? $json.response ?? $json;

let invoice;

// ============================================
// 2. PARSE QWEN RESPONSE
// ============================================

if (typeof raw === 'string') {
  let cleaned = raw.trim();

  // Remove Markdown code fences
  cleaned = cleaned
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  // Extract JSON object
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');

  if (start === -1 || end === -1 || end < start) {
    throw new Error(
      'No valid JSON object found in Qwen response: ' + cleaned
    );
  }

  let jsonString = cleaned.substring(start, end + 1);

  // --------------------------------------------
  // CLEAN COMMON QWEN JSON FORMATTING ISSUES
  // --------------------------------------------

  // Remove trailing commas before closing arrays/objects
  jsonString = jsonString.replace(/,\s*([}\]])/g, '$1');

  // Normalize smart quotation marks
  jsonString = jsonString
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'");

  try {
    invoice = JSON.parse(jsonString);

  } catch (error) {

    // ------------------------------------------
    // PROVIDE EXACT ERROR LOCATION
    // ------------------------------------------

    const positionMatch = error.message.match(/position\s+(\d+)/i);

    let errorDetails = '';

    if (positionMatch) {
      const position = Number(positionMatch[1]);

      const line = jsonString.substring(0, position).split('\n').length;

      const column = position -
        jsonString.lastIndexOf('\n', position - 1);

      const context = jsonString.substring(
        Math.max(0, position - 100),
        Math.min(jsonString.length, position + 100)
      );

      errorDetails =
        '\nLine: ' + line +
        '\nColumn: ' + column +
        '\nPosition: ' + position +
        '\nContext: ' + context;
    }

    throw new Error(
      'Failed to parse Qwen JSON: ' + error.message +
      errorDetails +
      '\nExtracted content: ' + jsonString
    );
  }

} else {
  invoice = raw;
}

// ============================================
// 3. VALIDATE INVOICE OBJECT
// ============================================

if (
  !invoice ||
  typeof invoice !== 'object' ||
  Array.isArray(invoice)
) {
  throw new Error(
    'Qwen response must contain a valid JSON object.'
  );
}

// ============================================
// 4. NORMALIZE VAT AND TAX
// ============================================

const taxCandidates = [
  invoice.tax,
  invoice.vat,
  invoice.VAT
];

const extractedTax = taxCandidates.find(value =>
  value !== undefined &&
  value !== null &&
  !(typeof value === 'string' && value.trim() === '')
);

invoice.tax = extractedTax ?? null;

// Remove duplicate VAT fields
delete invoice.vat;
delete invoice.VAT;

// ============================================
// 5. DEFINE PLACEHOLDERS
// ============================================

const placeholders = [
  'mm-dd-yy',
  'dd-mm-yy',
  'yyyy-mm-dd',
  'n/a',
  'not available',
  'unknown',
  'xxxxx'
];

// ============================================
// 6. NORMALIZE EMPTY AND PLACEHOLDER VALUES
// ============================================

for (const field of ['due_date', 'discount']) {
  const value = invoice[field];

  if (
    value === null ||
    value === undefined ||
    (
      typeof value === 'string' &&
      (
        value.trim() === '' ||
        placeholders.includes(value.trim().toLowerCase()) ||
        value.trim().startsWith('[')
      )
    )
  ) {
    invoice[field] = null;
  }
}

// ============================================
// 7. CHECK DOCUMENT TYPE
// ============================================

const isInvoice =
  typeof invoice.document_type === 'string' &&
  invoice.document_type.trim().toLowerCase() === 'invoice';

// ============================================
// 8. DEFINE REQUIRED FIELDS FOR MVP
// ============================================

const requiredFields = [
  'invoice_number',
  'invoice_date',
  'due_date',
  'vendor_name',
  'total',
  'discount',
  'tax'
];

// ============================================
// 9. FIND MISSING REQUIRED FIELDS
// ============================================

const missingFields = requiredFields.filter(field => {
  const value = invoice[field];

  return (
    value === null ||
    value === undefined ||
    (typeof value === 'string' && value.trim() === '')
  );
});

// ============================================
// 10. GET QWEN AI MISSING FIELDS
// ============================================

const aiMissingFields = Array.isArray(invoice.missing_fields)
  ? invoice.missing_fields
  : [];

// ============================================
// 11. RECONCILE QWEN MISSING FIELDS
// WITH ACTUAL INVOICE VALUES
// ============================================

const validAiMissingFields = aiMissingFields.filter(field => {

  // Only accept string field names
  if (typeof field !== 'string') {
    return false;
  }

  const normalizedField = field.trim().toLowerCase();

  // Ignore fields not required by the MVP
  if (!requiredFields.includes(normalizedField)) {
    return false;
  }

  const value = invoice[normalizedField];

  // Keep the field only if its actual value is empty
  return (
    value === null ||
    value === undefined ||
    (typeof value === 'string' && value.trim() === '')
  );
});

// ============================================
// 12. COMBINE MISSING FIELDS
// WITHOUT DUPLICATES
// ============================================

const allMissingFields = [...new Set([
  ...missingFields,
  ...validAiMissingFields
])];

// ============================================
// 13. REMOVE TAX FROM MISSING FIELDS
// IF TAX WAS SUCCESSFULLY EXTRACTED
// ============================================

if (invoice.tax !== null) {
  const taxIndex = allMissingFields.indexOf('tax');

  if (taxIndex !== -1) {
    allMissingFields.splice(taxIndex, 1);
  }
}

// ============================================
// 14. DETERMINE INVOICE COMPLETENESS
// ============================================

const isComplete =
  isInvoice && allMissingFields.length === 0;

// ============================================
// 15. UPDATE INVOICE OBJECT
// ============================================

invoice.missing_fields = allMissingFields;
invoice.is_complete = isComplete;

// ============================================
// 16. DETERMINE VALIDATION STATUS
// ============================================

const validationStatus = !isInvoice
  ? 'not_invoice'
  : isComplete
    ? 'complete'
    : 'incomplete';

// ============================================
// 17. RETURN FINAL RESULT TO N8N
// ============================================

return {
  json: {
    invoice,
    isInvoice,
    isComplete,
    missingFields: allMissingFields,
    validationStatus
  }
};

