const invoice = $json.invoice_data;

const message = $('Acknowledge Trigger').first().json.message.text;

const missingFields = $json.missing_fields || [];

const updates = {};

for (const field of missingFields) {
  const regex = new RegExp(
    `${field.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*:\\s*(-?\\d+(?:\\.\\d+)?)`,
    'i'
  );

  const match = message.match(regex);

  if (match) {
    updates[field] = Number(match[1]);
  }
}

const unprovidedFields = missingFields.filter(
  field => updates[field] === undefined
);

return {
  json: {
    invoice_id: $json.id,
    invoice_data: {
      ...invoice,
      ...updates,
      missing_fields: unprovidedFields,
      is_complete: unprovidedFields.length === 0
    },
    missing_fields: unprovidedFields,
    correction_complete: unprovidedFields.length === 0
  }
};
